{"revision_id":"b50e0112-5390-449f-a293-79d3de8ff916","source_sha256":"e21ea9db5d1cc1d12f3d8510608c2c38623170012608a9d27a768f4af1aae4a4","source":"module rising_edge(input clk, rst, din, output reg pulse);
reg previous;
always @(posedge clk) begin
  if (rst) begin
    previous <= 1'b0;
    pulse <= 1'b0;
  end else begin
    pulse <= din & ~previous;
    previous <= din;
  end
end
endmodule
